import{_ as a,o as e,c as o,ai as l}from"./chunks/framework.scx6l_IK.js";const s=JSON.parse('{"title":"处世","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-处世.md","filePath":"50-概念资料/dict-处世.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-处世.md"};function i(d,t,h,c,u,n){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="处世" tabindex="-1">处世 <a class="header-anchor" href="#处世" aria-label="Permalink to &quot;处世&quot;">​</a></h1><blockquote><p>传统：儒家 | 佛家对应：历境炼心 | 道家对应：和光同尘</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;处世&quot;就是<strong>在具体的人际关系和社会生活中修行</strong>。不是回避社会，而是在社会这个大道场里磨炼心性。</p><p>了空居士说：家庭是道场，工作单位是道场——修行不在蒲团上完成，在每一次待人接物中完成。处世的核心态度是&quot;与人为善&quot;——这是心能安静的基础。处世的方法论是&quot;用道理和良心和人家对论，守住这两条，永远立于不败之地。&quot;</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;家庭是道场，工作单位是道场，社会是道场。怎么去对待家庭？怎么去对待社会？就在日常生活中。&quot; — <a href="/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a></p></blockquote><blockquote><p>&quot;我们总结的经验就是用道理和良心和人家对论。评价一件事情都是用道理和良心，只要守住这两条，永远立于不败之地。&quot; — 修行入世（20090112b）</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>修行就是远离社会、清净独处</td><td>真正修行在日常——待人接物就是功夫</td></tr><tr><td>处世就是八面玲珑</td><td>处世是真诚待人、按道理办事，不是迎合</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-家庭道场">dict-家庭道场</a> — 家庭是处世的第一现场</li><li><a href="/50-概念资料/dict-敬">dict-敬</a> — 恭敬心是处世的基本态度</li><li><a href="/50-概念资料/dict-恕">dict-恕</a> — 恕是处世的底线原则</li><li><a href="/50-概念资料/dict-和光同尘">dict-和光同尘</a> — 道家的处世智慧版</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-历境炼心">model-历境炼心</a> — 处世就是历境炼心的具体现场</li><li><a href="/10-核心模型/model-自然务实">model-自然务实</a> — 在具体事务中抓核心、做实事</li><li><a href="/10-核心模型/model-圆融中和">model-圆融中和</a> — 处世不走极端</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>不把&quot;修行&quot;和&quot;生活&quot;分开——每一次待人接物都是修行。工作的认真、对人的客气、说话的温和，都是功夫。</p>',16)])])}const b=a(r,[["render",i]]);export{s as __pageData,b as default};
